insert into public.courses (id, programme_id, code, name, year, semester, area, ects, group_id, capacity, requires_approval, course_director, request_prompt, description, image, details) values
  ('c1', 'megsi', '14724', 'Corporate Strategy', 1, 'S1', 'G', 5, null, 0, false, null, null, 'The firm''s strategic management system: competitiveness, context, competitive advantage and strategic change.', 'https://images.unsplash.com/photo-1557804506-669a67965ba0?auto=format&fit=crop&w=900&q=70', '{"teachingType":"Presential","classHours":30,"classType":"Theory Practice","autonomousHours":110,"objectives":"Each learning outcome corresponds to one or several chapters of the syllabus.\n- The student is able to develop an up-to-date and integrated view of the firm''s strategic management system and context in all chapters of the program but more strongly in chapter 1.\n- The identification of competitiveness as a core concept in strategy is achieved in chapter 2.\n- The identification of the firm''s position in its context is presented in chapters 3 and 4.\n- The identification of firm'' strategies to develop competitive advantage is presented in chapter 5.\n- The comprehension of the firm as a system of relationships is achieved in chapter 6.\n- The explanation of the innovation processes and strategic change is carried out in chapter 7.","outcomes":["To acquire an up-to-date and integrated view of the firm''s strategic management system and context","To identify competitiveness as a core concept in strategy","To identify the firm''s position in its context","To identify strategies to develop competitive advantage","To understand the firm as a system of relationships","To explain innovation processes and strategic change"],"program":[{"title":"Strategy","text":"The concept of strategy, its different meanings, and its utility and role in the firm."},{"title":"Strategy and competitiveness","text":"Competitiveness as the basis of strategy and distinguishes related concepts such as performance and competition."},{"title":"Strategy and context","text":"The context of strategy including the macro-environment, industry, and strategic groups."},{"title":"Resources, activities and competencies","text":"The firm as a complex set of resources, activities and competencies."},{"title":"Strategic options and business models","text":"Business strategies, business models, and corporate strategies."},{"title":"Organizational relationships and networks","text":"The firm as a system of intra and inter-organizational relationships that involve strategic alliances, mergers and acquisitions, and other more complex forms of relationships such as networks."},{"title":"Innovation and organizational dynamics","text":"Types and strategies of innovation, and explains organizational change from a strategic perspective."}],"bibliography":["Dess, Gregory D.; McNamara, G.; Eisner, Alan; Lee, Seung-Hyun (2019). Strategic Management: Creating Competitive Advantage, 9/e, McGraw-Hill Higher Education, New York.","Grant, Robert M. (2018). Contemporary Strategy Analysis, 10/e, Wiley, Chichester.","Johnson, Gerry; Whittington, Richard; Scholes, Kevan; Angwin, Duncan; Regnér, Patrick (2017). Exploring Strategy, 11/e, Pearson Education, Harlow.","Paroutis, Sotirios; Heracleous, Loizos; Angwin, Duncan (2016). Practicing Strategy: Text and Cases, 2/e, Sage Publications, London.","Wit, Bob de (2017). Strategy: An International Perspective, 6/e, Cengage Learning, Andover."],"teachingMethods":"The classes combine theoretical-practical exposition of the syllabus contents with the analysis and practical discussion of projects and/or case studies. Attendance of classes is compulsory under the terms of the academic regulations. Participation, attendance, and punctuality of students are strongly recommended.\nStudents'' evaluation can integrate several instruments according to the academic regulations, such as: participation in class, which includes not only attendance but also the active participation in class and the resolution of practical questions/cases (either in group or individually); individual works; group work; projects; essays; and tests.","assessment":"The instruments and weights are specified each year in the course unit dossier. For instance, there may be two assessment elements as follows: participation, discussion and presentation of case studies (30-50%); and final test (50-70%)."}'::jsonb),
  ('c2', 'megsi', 'UC102', 'Information Presentation and Visualization', 1, 'S1', 'TSI', 5, null, 0, false, null, null, 'Turning data into clear visual representations that support understanding and decisions.', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=900&q=70', '{"teachingType":"Presential","classHours":30,"classType":"Theory Practice","autonomousHours":110}'::jsonb),
