  ('c4', 'megsi', 'UC104', 'Information Technologies Infrastructures', 1, 'S1', 'TSI', 5, null, 0, false, null, null, 'The hardware, network and platform foundations that information systems run on.', 'https://images.unsplash.com/photo-1558494949-ef010cbdcc31?auto=format&fit=crop&w=900&q=70', '{"teachingType":"Presential","classHours":30,"classType":"Theory Practice","autonomousHours":110}'::jsonb),
